{
  "title": "High Frequency DNS TXT Queries to Single Domain",
  "id": "RULE-2026-001",
  "status": "experimental",
  "description": "Detect possible DNS tunneling via excessive TXT record queries to the same domain.",
  "author": "SOC Team",
  "logsource": {
    "product": "dns",
    "service": "bind"
  },
  "detection": {
    "selection": {
      "query_type": "TXT",
      "query": "*"
    },
    "groupby": {
      "field": "query",
      "timeframe": "1m",
      "threshold": 300
    },
    "condition": "selection and groupby"
  },
  "fields": ["src_ip", "dest_ip", "query"],
  "falsepositives": ["Legitimate bulk DNS queries"],
  "level": "high"
}
